import{_ as a,o as r,c as t,a5 as o}from"./chunks/framework.PLGyiLjE.js";const u=JSON.parse('{"title":"Hard mode, Daily and Weekly","description":"","frontmatter":{},"headers":[],"relativePath":"guides/hard-vigil-daily.md","filePath":"guides/hard-vigil-daily.md"}'),l={name:"guides/hard-vigil-daily.md"};function s(i,e,n,d,h,g){return r(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="hard-mode-daily-and-weekly" tabindex="-1">Hard mode, Daily and Weekly <a class="header-anchor" href="#hard-mode-daily-and-weekly" aria-label="Permalink to &quot;Hard mode, Daily and Weekly&quot;">​</a></h1><h2 id="hard-mode" tabindex="-1">Hard mode <a class="header-anchor" href="#hard-mode" aria-label="Permalink to &quot;Hard mode&quot;">​</a></h2><p>Hard Adventure is the same road after dark: tougher foes, better spoils.</p><ul><li>Opens after you clear <strong>1-5</strong> on Normal.</li><li>Each stage opens on Hard after its Normal clear.</li><li>Hard is its own chain: to play a stage on Hard, clear the stage before it on Hard first.</li><li>Play alone or with up to <strong>three fighters</strong>.</li></ul><h2 id="daily-challenge" tabindex="-1">Daily challenge <a class="header-anchor" href="#daily-challenge" aria-label="Permalink to &quot;Daily challenge&quot;">​</a></h2><p>Opens after you clear <strong>2-1</strong>. Each day picks one of your furthest stages and adds a twist:</p><ul><li><strong>One life:</strong> no revives. Fall once and the run is over.</li><li><strong>Double elites:</strong> every elite comes with a twin.</li><li><strong>Beat the clock:</strong> clear it before time runs out. Win once a day for silver and materials. Days 3 and 7 of a streak pay extra. Miss a day and the streak starts over. New challenges come at 00:00 UTC.</li></ul><h2 id="weekly-goals" tabindex="-1">Weekly goals <a class="header-anchor" href="#weekly-goals" aria-label="Permalink to &quot;Weekly goals&quot;">​</a></h2><p>Open after you clear <strong>2-5</strong>. Up to three goals each week, such as clearing a stage under par or on Hard. Finish all three for <strong>Rare gear</strong>. New goals every Monday.</p><h2 id="score-style-and-medals" tabindex="-1">Score, style and medals <a class="header-anchor" href="#score-style-and-medals" aria-label="Permalink to &quot;Score, style and medals&quot;">​</a></h2><ul><li><strong>Score:</strong> bigger foes give more points, and finishing under par adds a time bonus.</li><li><strong>Style:</strong> use lots of different moves for a better grade (S is the best).</li><li><strong>Stage medals:</strong> <strong>No knockouts</strong>, <strong>Style A+</strong> and <strong>Hard par</strong> (beat the par time on Hard).</li></ul><h2 id="coming-later" tabindex="-1">Coming later <a class="header-anchor" href="#coming-later" aria-label="Permalink to &quot;Coming later&quot;">​</a></h2><p>The Vigil Road and the Wick Trial open in a later update.</p>',13)])])}const m=a(l,[["render",s]]);export{u as __pageData,m as default};
